update public.site_settings set data = jsonb_set(jsonb_set(jsonb_set(jsonb_set(data, '{content,ar,faq}', '[{"q": "ما الخدمات التي تقدمونها؟", "a": "مواقع ومنصات إلكترونية، تطبيقات جوال، أنظمة إدارة مخصصة، تصميم واجهات، استضافة وحلول سحابية، ذكاء اصطناعي وأتمتة، حماية البيانات، ودعم وصيانة."}, {"q": "كم يستغرق تنفيذ المشروع؟", "a": "حسب حجمه وميزاته. نتفق معك على جدول زمني بمراحل واضحة قبل البدء، وتتابع التقدم أسبوعياً على نسخة تجريبية."}, {"q": "كم تكلفة المشروع؟", "a": "الباقات تبدأ من 500$. للتقدير الفوري استخدم حاسبة التكلفة في صفحة الباقات، والسعر النهائي في عرض مكتوب لا نبدأ قبل موافقتك عليه."}, {"q": "كيف يتم الدفع؟", "a": "دفعتان فقط: 75% عند بدء العمل، و25% بعد التسليم وتأكدك أن العمل كما اتفقنا."}, {"q": "هل تدعم مشاريعكم العربية والإنجليزية؟", "a": "نعم، بلغتين معاً مع دعم كامل للكتابة من اليمين إلى اليسار."}, {"q": "هل يمكن إضافة الدفع الإلكتروني؟", "a": "نعم، ليستقبل عملاؤك المدفوعات مباشرة من موقعك أو متجرك أو تطبيقك."}, {"q": "هل أستطيع تعديل محتوى موقعي بنفسي؟", "a": "نعم، بلوحة تحكم سهلة تعدّل منها النصوص والصور دون الحاجة إلى مبرمج."}, {"q": "هل تقدمون دعماً بعد التسليم؟", "a": "نعم، دعم فني مجاني لمدة سنة من التسليم، ثم خطة صيانة وتطوير حسب حاجتك."}, {"q": "كيف نبدأ؟", "a": "اضغط «ابدأ مشروعك» واختر ما يناسبك، أو راسلنا على واتساب، ونتصل بك خلال يوم عمل."}]'::jsonb, true), '{content,en,faq}', '[{"q": "What services do you offer?", "a": "Websites and platforms, mobile apps, custom business systems, UI/UX design, hosting and cloud, AI and automation, data protection, and support and maintenance."}, {"q": "How long does a project take?", "a": "It depends on size and features. We agree a timeline with clear milestones before we start, and you follow progress weekly on a test version."}, {"q": "How much does a project cost?", "a": "Packages start at $500. For an instant estimate use the cost calculator on the packages page; the final price comes in a written quote we only start on once you approve it."}, {"q": "How do I pay?", "a": "Just two payments: 75% when work starts and 25% after delivery, once you''ve confirmed the work is as agreed."}, {"q": "Do your projects support Arabic and English?", "a": "Yes, both together, with full right-to-left support."}, {"q": "Can you add online payments?", "a": "Yes, so your customers can pay you directly on your site, store or app."}, {"q": "Can I edit my site''s content myself?", "a": "Yes, with an easy dashboard for your texts and images — no developer needed."}, {"q": "Do you offer support after delivery?", "a": "Yes: free technical support for one year after delivery, then a maintenance plan that fits your needs."}, {"q": "How do we start?", "a": "Tap “Start your project” and pick what suits you, or message us on WhatsApp — we''ll call you within one working day."}]'::jsonb, true), '{content,ar,partners_sub}', to_jsonb('شركات ومشاريع عملنا معها.'::text), true), '{content,en,partners_sub}', to_jsonb('Companies and projects we''ve worked with.'::text), true) where id = 1 and data ? 'content' returning jsonb_array_length(data->'content'->'ar'->'faq') as ar_faq, jsonb_array_length(data->'content'->'en'->'faq') as en_faq;